// HasIssue applies the HasEdge predicate on the "issue" edge.
func HasIssue() predicate.SupportIssueAttachment {
	return predicate.SupportIssueAttachment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IssueTable, IssueColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIssueWith applies the HasEdge predicate on the "issue" edge with a given conditions (other predicates).
func HasIssueWith(preds ...predicate.SupportIssue) predicate.SupportIssueAttachment {
	return predicate.SupportIssueAttachment(func(s *sql.Selector) {
		step := newIssueStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SupportIssueAttachment) predicate.SupportIssueAttachment {
	return predicate.SupportIssueAttachment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SupportIssueAttachment) predicate.SupportIssueAttachment {
	return predicate.SupportIssueAttachment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SupportIssueAttachment) predicate.SupportIssueAttachment {
	return predicate.SupportIssueAttachment(sql.NotPredicates(p))
}
